  model_grader_token_usage_per_model: unknown;
}

model ValidateGraderRequest {
  /** The grader used for the fine-tuning job. */
  grader:
    | GraderStringCheck
    | GraderTextSimilarity
    | GraderPython
    | GraderScoreModel
    | GraderMulti;
